def require_authentication():
    """
    Stop execution before any dashboard data is displayed
    unless authentication succeeds.
    """

    if "authenticated" not in st.session_state:
        st.session_state[
            "authenticated"
        ] = False

    if "authenticated_username" not in st.session_state:
        st.session_state[
            "authenticated_username"
        ] = ""

    if not st.session_state["authenticated"]:

        render_login_page()

        st.stop()

    render_premium_header()



# ============================================================
# GENERAL COLUMN FINDER
# ============================================================

def find_column(df, possible_names):

    normalized_columns = {}

    for column in df.columns:

        normalized = (
            str(column)
            .lower()
            .replace("\n", " ")
            .replace("\r", " ")
            .strip()
        )

        normalized_columns[normalized] = column

    # Exact match

    for name in possible_names:

        target = name.lower().strip()

        if target in normalized_columns:
            return normalized_columns[target]

    # Partial match

    for column in df.columns:

        normalized = (
            str(column)
            .lower()
            .replace("\n", " ")
            .replace("\r", " ")
            .strip()
        )

        for name in possible_names:

            target = name.lower().strip()

            if target in normalized:
                return column

    return None


