@st.cache_data
def load_insem_data():

    df = pd.read_excel(
        INSEM_FILE,
        sheet_name="Final-Insem-1-Marks",
        engine="xlrd"
    )

    df.columns = (
        df.columns
        .astype(str)
        .str.strip()
    )

    id_column = find_column(
        df,
        [
            "University Id",
            "University ID",
            "ID Number",
            "Student ID"
        ]
    )

    if id_column is None:

        raise ValueError(
            "University ID column was not found "
            "in the In-Semester file."
        )

    df = df.rename(
        columns={
            id_column: "University Id"
        }
    )

    df["University Id"] = clean_student_id(
        df["University Id"]
    )

    total_column = find_column(
        df,
        [
            "Total",
            "Total Marks",
            "In Sem Total",
            "In-Sem Total"
        ]
    )

    if total_column is None:

        raise ValueError(
            "Total marks column was not found "
            "in the In-Semester file."
        )

    df = df.rename(
        columns={
            total_column: "Total"
        }
    )

    df["Total"] = pd.to_numeric(
        df["Total"],
        errors="coerce"
    )

    course_code_column = find_column(
        df,
        [
            "Course Code",
            "CourseCode"
        ]
    )

    if course_code_column is not None:

        df = df.rename(
            columns={
                course_code_column:
                "Course Code"
            }
        )

    course_name_column = find_column(
        df,
        [
            "Course Name",
            "Course Title",
            "CourseName"
        ]
    )

    if course_name_column is not None:

        df = df.rename(
            columns={
                course_name_column:
                "Course Name"
            }
        )

    return df


