@st.cache_data
def load_result_file(
    file_path,
    regulation
):

    df = pd.read_excel(
        file_path,
        sheet_name=0
    )

    df.columns = (
        df.columns
        .astype(str)
        .str.replace(
            "\n",
            " ",
            regex=False
        )
        .str.replace(
            "\r",
            " ",
            regex=False
        )
        .str.strip()
    )

    id_column = find_column(
        df,
        [
            "ID Number",
            "ID",
            "University ID",
            "University Id",
            "Student ID"
        ]
    )

    name_column = find_column(
        df,
        [
            "Name",
            "Student Name",
            "Name of the student"
        ]
    )

    course_code_column = find_column(
        df,
        [
            "Course Code"
        ]
    )

    course_name_column = find_column(
        df,
        [
            "Course Name",
            "Course Title"
        ]
    )

    grade_column = find_column(
        df,
        [
            "Grade"
        ]
    )

    category_column = find_column(
        df,
        [
            "Category"
        ]
    )

    ay_column = find_column(
        df,
        [
            "AY",
            "Academic Year",
            "AcademicYear"
        ]
    )

    semester_column = find_column(
        df,
        [
            "Semester",
            "Sem"
        ]
    )

    missing = []

    if id_column is None:
        missing.append("ID Number")

    if course_code_column is None:
        missing.append("Course Code")

    if course_name_column is None:
        missing.append("Course Name")

    if grade_column is None:
        missing.append("Grade")

    if category_column is None:
        missing.append("Category")

    if ay_column is None:
        missing.append("AY")

    if semester_column is None:
        missing.append("Semester")

    if missing:

        raise ValueError(
            f"{regulation} result file is missing columns: "
            + ", ".join(missing)
        )

    rename_map = {

        id_column:
        "Student ID",

        course_code_column:
        "Course Code",

        course_name_column:
        "Course Name",

        grade_column:
        "Grade",

        category_column:
        "Category",

        ay_column:
        "AY",

        semester_column:
        "Semester"
    }

    if name_column is not None:

        rename_map[
            name_column
        ] = "Name"

    df = df.rename(
        columns=rename_map
    )

    df["Student ID"] = clean_student_id(
        df["Student ID"]
    )

    df["AY"] = (
        df["AY"]
        .astype(str)
        .str.strip()
    )

    df["Semester"] = (
        df["Semester"]
        .astype(str)
        .str.strip()
    )

    df["Grade"] = (
        df["Grade"]
        .astype(str)
        .str.strip()
    )

    df["Category"] = (
        df["Category"]
        .astype(str)
        .str.strip()
        .str.upper()
    )

    df["Course Code"] = (
        df["Course Code"]
        .astype(str)
        .str.strip()
    )

    df["Course Name"] = (
        df["Course Name"]
        .astype(str)
        .str.strip()
    )

    df["Regulation"] = regulation

    return df


# ============================================================
# LOAD ALL RESULT FILES
# ============================================================

def load_all_results():

    frames = []

    if Y23_FILE.exists():

        frames.append(
            load_result_file(
                Y23_FILE,
                "Y-23"
            )
        )

    if Y24_FILE.exists():

        frames.append(
            load_result_file(
                Y24_FILE,
                "Y-24"
            )
        )

    if Y25_FILE.exists():

        frames.append(
            load_result_file(
                Y25_FILE,
                "Y-25"
            )
        )

    if not frames:

        raise FileNotFoundError(
            "No Result Analysis Excel files were found."
        )

    return pd.concat(
        frames,
        ignore_index=True
    )


# ============================================================
# LOAD CGPA DATA
# ============================================================

@st.cache_data
def load_cgpa_data():

    if not CGPA_FILE.exists():

        return pd.DataFrame(
            columns=[
                "Student ID",
                "CGPA"
            ]
        )

    df = pd.read_excel(
        CGPA_FILE,
        sheet_name=0
    )

    df.columns = (
        df.columns
        .astype(str)
        .str.replace(
            "\n",
            " ",
            regex=False
        )
        .str.replace(
            "\r",
            " ",
            regex=False
        )
        .str.strip()
    )

    student_id_column = find_column(
        df,
        [
            "Student ID",
            "StudentID",
            "ID Number",
            "University ID",
            "University Id"
        ]
    )

    cgpa_column = find_column(
        df,
        [
            "CGPA",
            "C.G.P.A"
        ]
    )

    if student_id_column is None:

        raise ValueError(
            "Student ID column was not found "
            "in CGPA.xlsx."
        )

    if cgpa_column is None:

        raise ValueError(
            "CGPA column was not found "
            "in CGPA.xlsx."
        )

    df = df.rename(
        columns={
            student_id_column:
            "Student ID",

            cgpa_column:
            "CGPA"
        }
    )

    df["Student ID"] = clean_student_id(
        df["Student ID"]
    )

    df["CGPA"] = pd.to_numeric(
        df["CGPA"],
        errors="coerce"
    )

    return (
        df[
            [
                "Student ID",
                "CGPA"
            ]
        ]
        .drop_duplicates(
            subset=["Student ID"],
            keep="first"
        )
    )

# ============================================================
# PARENT PDF REPORT GENERATOR
# ============================================================

def _pdf_text(value):

    if value is None:
        return "-"

    try:
        if pd.isna(value):
            return "-"
    except Exception:
        pass

    return str(value).strip()


def _pdf_paragraph(value, style):

    safe_text = html.escape(
        _pdf_text(value)
    )

    return Paragraph(
        safe_text,
        style
    )


