# ============================================================
# GET SEMESTER NUMBER
# ============================================================

def get_semester_number(
    regulation,
    ay,
    semester
):

    ay_text = (
        str(ay)
        .strip()
        .lower()
        .replace("_", "-")
    )

    semester_text = (
        str(semester)
        .strip()
        .lower()
    )

    if "odd" in semester_text:

        term = "Odd Sem"

    elif "even" in semester_text:

        term = "Even Sem"

    elif "odd" in ay_text:

        term = "Odd Sem"

    elif "even" in ay_text:

        term = "Even Sem"

    else:

        term = ""

    match = re.search(
        r"(20\d{2})\D+(20\d{2})",
        ay_text
    )

    if match:

        y1 = match.group(1)
        y2 = match.group(2)

        normalized_ay = (
            f"{y1}-{y2}"
        )

    else:

        normalized_ay = (
            str(ay).strip()
        )

    lookup_key = (
        f"{normalized_ay} {term}"
    )

    regulation_map = (
        SEMESTER_MAPPING
        .get(
            regulation,
            {}
        )
    )

    return regulation_map.get(
        lookup_key,
        None
    )



# ============================================================
# REGULATION-WISE PERFORMANCE SUMMARY
# ============================================================

def build_regulation_summary(results_df):
    """
    Build regulation-wise student performance statistics.

    Definitions:
    - Passed Students:
      Students whose latest available status for every course
      is P (no current backlog).
    - Pass Percentage:
      Passed Students / Total Students * 100.
    - Passed Students:
      Students whose latest available status for every course
      is P (after excluding the "-" category for the dashboard).

    Only P is treated as passed, consistent with the existing
    Student Academic Performance Portal logic.
    """

    if (
        not isinstance(results_df, pd.DataFrame)
        or results_df.empty
    ):
        return pd.DataFrame(
            columns=[
                "Regulation",
                "Total Students",
                "Passed Students",
                "Pass Percentage"
            ]
        )

    df = results_df.copy()

    required_columns = [
        "Student ID",
        "Regulation",
        "Course Code",
        "Category"
    ]

    missing = [
        column
        for column in required_columns
        if column not in df.columns
    ]

    if missing:
        return pd.DataFrame(
            columns=[
                "Regulation",
                "Total Students",
                "Passed Students",
                "Pass Percentage"
            ]
        )

    df["Student ID"] = (
        df["Student ID"]
        .astype(str)
        .str.strip()
    )

    df["Regulation"] = (
        df["Regulation"]
        .astype(str)
        .str.strip()
    )

    df["Course Code"] = (
        df["Course Code"]
        .astype(str)
        .str.strip()
    )

    df["Category Clean"] = (
        df["Category"]
        .fillna("-")
        .astype(str)
        .str.strip()
        .str.upper()
    )

    df.loc[
        df["Category Clean"].isin(
            ["", "NAN", "NONE"]
        ),
        "Category Clean"
    ] = "-"

    # Create a reliable semester order so repeated courses can
    # be evaluated from earlier attempt -> latest attempt.
    if "Semester Number" not in df.columns:
        df["Semester Number"] = df.apply(
            lambda row:
            get_semester_number(
                row.get("Regulation", ""),
                row.get("AY", ""),
                row.get("Semester", "")
            ),
            axis=1
        )

    semester_order = [
        "1-1", "1-2",
        "2-1", "2-2",
        "3-1", "3-2",
        "4-1", "4-2"
    ]

    semester_rank = {
        value: index
        for index, value
        in enumerate(semester_order)
    }

    df["Semester Rank"] = (
        df["Semester Number"]
        .map(semester_rank)
        .fillna(999)
    )

    # Preserve source order as a final tie-breaker.
    df["_source_order"] = range(len(df))

    # --------------------------------------------------------
    # Historical backlog status for each student.
    # --------------------------------------------------------

    student_history = (
        df.groupby(
            ["Regulation", "Student ID"],
            dropna=False
        )["Category Clean"]
        .apply(
            lambda series:
            (series != "P").any()
        )
        .reset_index(
            name="Ever Had Backlog"
        )
    )

    # --------------------------------------------------------
    # Latest result for each student + course.
    # --------------------------------------------------------

    latest_course = (
        df.sort_values(
            by=[
                "Regulation",
                "Student ID",
                "Course Code",
                "Semester Rank",
                "_source_order"
            ]
        )
        .drop_duplicates(
            subset=[
                "Regulation",
                "Student ID",
                "Course Code"
            ],
            keep="last"
        )
        .copy()
    )

    latest_backlog = (
        latest_course.groupby(
            ["Regulation", "Student ID"],
            dropna=False
        )["Category Clean"]
        .apply(
            lambda series:
            (series != "P").any()
        )
        .reset_index(
            name="Current Backlog"
        )
    )

    student_status = student_history.merge(
        latest_backlog,
        on=[
            "Regulation",
            "Student ID"
        ],
        how="left"
    )

    student_status["Passed"] = (
        ~student_status["Current Backlog"]
    )

    # --------------------------------------------------------
    # PASS PERCENTAGE ONLY:
    # Ignore "-" category rows for every regulation.
    #
    # IMPORTANT:
    # This calculation is separate from the "Students Passed"
    # graph. The passed-student graph keeps the existing logic.
    # For pass percentage, rows whose Category is "-" are
    # completely excluded before deciding the student's latest
    # course status.
    # --------------------------------------------------------

    percentage_df = df[
        df["Category Clean"] != "-"
    ].copy()

    percentage_df = (
        percentage_df
        .sort_values(
            by=[
                "Regulation",
                "Student ID",
                "Course Code",
                "Semester Rank",
                "_source_order"
            ]
        )
        .drop_duplicates(
            subset=[
                "Regulation",
                "Student ID",
                "Course Code"
            ],
            keep="last"
        )
    )

    percentage_student_status = (
        percentage_df
        .groupby(
            ["Regulation", "Student ID"],
            dropna=False
        )["Category Clean"]
        .apply(
            lambda series:
            (series == "P").all()
        )
        .reset_index(
            name="Passed For Percentage"
        )
    )

    percentage_summary = (
        percentage_student_status
        .groupby(
            "Regulation",
            dropna=False
        )
        .agg(
            **{
                "Percentage Eligible Students": (
                    "Student ID",
                    "nunique"
                ),
                "Percentage Passed Students": (
                    "Passed For Percentage",
                    "sum"
                )
            }
        )
        .reset_index()
    )

    # --------------------------------------------------------
    # STUDENTS PASSED GRAPH:
    # Ignore "-" category rows here as well.
    #
    # This uses the same meaningful-result dataset as the
    # pass-percentage graph, so both charts use the same rule.
    # A student is counted as passed when every remaining/latest
    # course result is P.
    # --------------------------------------------------------

    summary = (
        percentage_student_status
        .groupby(
            "Regulation",
            dropna=False
        )
        .agg(
            **{
                "Total Students": (
                    "Student ID",
                    "nunique"
                ),
                "Passed Students": (
                    "Passed For Percentage",
                    "sum"
                )
            }
        )
        .reset_index()
    )

    summary = summary.merge(
        percentage_summary,
        on="Regulation",
        how="left"
    )

    summary["Pass Percentage"] = (
        summary["Percentage Passed Students"]
        / summary["Percentage Eligible Students"]
        .replace(0, pd.NA)
        * 100
    )

    summary["Pass Percentage"] = (
        summary["Pass Percentage"]
        .fillna(0)
        .astype(float)
    )

    regulation_order = [
        "Y-23",
        "Y-24",
        "Y-25"
    ]

    summary["Regulation Sort"] = (
        summary["Regulation"]
        .map(
            {
                value: index
                for index, value
                in enumerate(regulation_order)
            }
        )
        .fillna(999)
    )

    summary = (
        summary
        .sort_values(
            "Regulation Sort"
        )
        .drop(
            columns=[
                "Regulation Sort"
            ]
        )
        .reset_index(
            drop=True
        )
    )

    return summary




# ============================================================
# TOP 3 STUDENTS — REGULATION WISE
# ============================================================

def display_top_students_by_regulation(
    results_df,
    cgpa_df,
    mentor_df
):
    """
    Display the top 3 students by CGPA for Y-23, Y-24 and Y-25
    in three compact side-by-side regulation cards.

    Only Rank, Student ID and CGPA are displayed to optimize space.
    """

    required_result_columns = [
        "Student ID",
        "Regulation"
    ]

    if (
        not isinstance(results_df, pd.DataFrame)
        or results_df.empty
        or any(
            column not in results_df.columns
            for column in required_result_columns
        )
    ):
        return

    if (
        not isinstance(cgpa_df, pd.DataFrame)
        or cgpa_df.empty
        or "Student ID" not in cgpa_df.columns
        or "CGPA" not in cgpa_df.columns
    ):
        return

    student_master = results_df[
        [
            "Student ID",
            "Regulation"
        ]
    ].copy()

    student_master["Student ID"] = (
        student_master["Student ID"]
        .astype(str)
        .str.strip()
    )

    student_master["Regulation"] = (
        student_master["Regulation"]
        .astype(str)
        .str.strip()
        .str.upper()
    )

    student_master = (
        student_master
        .sort_values(
            [
                "Regulation",
                "Student ID"
            ]
        )
        .drop_duplicates(
            subset=[
                "Regulation",
                "Student ID"
            ],
            keep="first"
        )
    )

    cgpa_data = cgpa_df[
        [
            "Student ID",
            "CGPA"
        ]
    ].copy()

    cgpa_data["Student ID"] = (
        cgpa_data["Student ID"]
        .astype(str)
        .str.strip()
    )

    cgpa_data["CGPA"] = pd.to_numeric(
        cgpa_data["CGPA"],
        errors="coerce"
    )

    cgpa_data = (
        cgpa_data
        .dropna(
            subset=["CGPA"]
        )
        .drop_duplicates(
            subset=["Student ID"],
            keep="first"
        )
    )

    top_students = student_master.merge(
        cgpa_data,
        on="Student ID",
        how="inner"
    )

    top_students = top_students[
        top_students["Regulation"].isin(
            [
                "Y-23",
                "Y-24",
                "Y-25"
            ]
        )
    ].copy()

    if top_students.empty:
        return

    regulation_order = [
        "Y-23",
        "Y-24",
        "Y-25"
    ]

    top_students["Regulation Sort"] = (
        top_students["Regulation"].map(
            {
                "Y-23": 1,
                "Y-24": 2,
                "Y-25": 3
            }
        )
    )

    top_students = (
        top_students
        .sort_values(
            [
                "Regulation Sort",
                "CGPA",
                "Student ID"
            ],
            ascending=[
                True,
                False,
                True
            ]
        )
        .groupby(
            "Regulation",
            sort=False,
            group_keys=False
        )
        .head(3)
        .copy()
    )

    top_students["Rank"] = (
        top_students
        .groupby("Regulation")
        .cumcount()
        + 1
    )

    regulation_cards = []

    for regulation in regulation_order:

        regulation_students = (
            top_students[
                top_students["Regulation"] == regulation
            ]
            .sort_values("Rank")
        )

        if regulation_students.empty:
            continue

        rows_html = []

        for _, row in regulation_students.iterrows():

            rank = int(row["Rank"])

            student_id = html.escape(
                str(row["Student ID"])
            )

            cgpa = f"{float(row['CGPA']):.2f}"

            if rank == 1:
                rank_class = "top3-rank-1"
                rank_text = "🥇 1"
            elif rank == 2:
                rank_class = "top3-rank-2"
                rank_text = "🥈 2"
            else:
                rank_class = "top3-rank-3"
                rank_text = "🥉 3"

            rows_html.append(
                f"""
                <tr>
                    <td class="rank-cell {rank_class}">
                        {rank_text}
                    </td>

                    <td class="id-cell">
                        {student_id}
                    </td>

                    <td class="cgpa-cell">
                        {cgpa}
                    </td>
                </tr>
                """
            )

        regulation_cards.append(
            f"""
            <div class="top3-regulation-card">

                <div class="top3-regulation-header">
                    {regulation}
                </div>

                <div class="top3-regulation-subtitle">
                    Top 3 performers by CGPA
                </div>

                <table class="top3-mini-table">

                    <thead>
                        <tr>
                            <th>Rank</th>
                            <th>Student ID</th>
                            <th>CGPA</th>
                        </tr>
                    </thead>

                    <tbody>
                        {"".join(rows_html)}
                    </tbody>

                </table>

            </div>
            """
        )

    st.html(
        """
        <div class="top3-card">

            <div class="top3-title">
                🏆 TOP 3 ACADEMIC PERFORMERS — REGULATION WISE
            </div>

            <div class="top3-subtitle">
                Top three students in each regulation based on CGPA.
            </div>

            <div class="top3-regulation-grid">
        """
        + "".join(regulation_cards)
        +
        """
            </div>

        </div>
        """
    )




